  ao = mix(ao, (0.85 + 0.15 * tuft) * mix(1.0, mossT.a, 0.5), grassCov);
  ao = mix(ao, 0.82 + 0.18 * clump.b, mossCov * (1.0 - grassCov));   // moss: soft cushion shading, no dark specks

